// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public {
        c = new GameItems(address(this), address(this));
        c.adjustAdminAccess(address(this), true);
    }

    function testFuzz_property(uint256 tokenIdSeed, uint256 quantity) public {
        quantity = bound(quantity, 1, 1000);
        address holder = address(uint160(uint256(keccak256(abi.encode(tokenIdSeed)))));
        vm.assume(holder != address(0));

        c.createGameItem("Test", "", false, true, 1000000, 1, type(uint16).max);

        MockNeuron mockNrn = new MockNeuron();
        c.instantiateNeuronContract(address(mockNrn));

        mockNrn.setBalanceOf(holder, type(uint256).max);

        uint256 tokenId = 0;

        vm.startPrank(holder);
        c.mint(tokenId, quantity);
        vm.stopPrank();

        uint256 balance = c.balanceOf(holder, tokenId);

        assertTrue(balance == quantity);
    }
}

contract MockNeuron {
    mapping(address => uint256) private _balances;

    function setBalanceOf(address account, uint256 amount) external {
        _balances[account] = amount;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function approveSpender(address, uint256) external pure {}

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }
}
